function handler(event) {
  var request = event.request;
  if (request.headers.host.value !== 'www.h-v-m.agency') return request;
  var query = [];
  for (var key in request.querystring) {
    var entry = request.querystring[key];
    var values = entry.multiValue || [entry];
    for (var i = 0; i < values.length; i++) {
      query.push(key + '=' + values[i].value);
    }
  }
  return {
    statusCode: 301,
    statusDescription: 'Moved Permanently',
    headers: { location: { value: 'https://h-v-m.agency' + request.uri + (query.length ? '?' + query.join('&') : '') } }
  };
}
